function abbeyCross(c) {
  c.save(); c.translate(60, 0);
  c.beginPath(); c.moveTo(56, -36); c.lineTo(71, -36); c.lineTo(71, -20);
  c.lineTo(87, -20); c.lineTo(87, -5); c.lineTo(71, -5); c.lineTo(71, 11);
  c.lineTo(56, 11); c.lineTo(56, -5); c.lineTo(40, -5); c.lineTo(40, -20);
  c.lineTo(56, -20); c.closePath(); c.fill(); c.restore();
}
